    "title": "超千只基金业绩翻倍，公募正从“卖产品”转向“配资产”",
    "link": "https://36kr.com/newsflashes/4002319582089090?f=rss",
    "pub_date": "2026-09-28 08:27:57",
    "author": "",
    "description": "在科技成长产业景气的带动下，公募基金迎来一轮业绩大丰收。数据显示，近两年全市场绝大多数基金斩获正收益，千余只基金实现收益翻倍，多只产品收益率突破500%。纵观过去两年，市场定价主线由估值修复切换至盈利驱动，AI产业链逐步成为行情核心，科技成长资产由产业重估迈入盈利兑现阶段，重仓光通信、半导体等方向的基金净值表现尤为突出。伴随行情演进，ETF板块快速壮大，公募行业也告别明星爆款模式，向平台化、“货架”式产品体系转型。（证券时报）",
    "content": "在科技成长产业景气的带动下，公募基金迎来一轮业绩大丰收。数据显示，近两年全市场绝大多数基金斩获正收益，千余只基金实现收益翻倍，多只产品收益率突破500%。纵观过去两年，市场定价主线由估值修复切换至盈利驱动，AI产业链逐步成为行情核心，科技成长资产由产业重估迈入盈利兑现阶段，重仓光通信、半导体等方向的基金净值表现尤为突出。伴随行情演进，ETF板块快速壮大，公募行业也告别明星爆款模式，向平台化、“货架”式产品体系转型。（证券时报）"
