    "content": "2026年09月28日 本报联合国9月26日电&nbsp;&nbsp;（记者李志伟）当地时间2026年9月26日，国家副主席韩正在纽约联合国总部出席第81届联合国大会一般性辩论并发表讲话。 韩正指出，当前国际形势变乱交织，地缘冲突延宕不止、发展鸿沟持续扩大、全球性挑战层出不穷。习近平主席在第76届联合国大会上提出全球发展倡议，之后又相继提出全球安全倡议、全球文明倡议、全球治理倡议，为构建人类命运共同体提供了战略指引。越来越多的国家愿携起手来，担当历史使命，应对困难挑战，增进人类共同福祉。 韩正提出四点建议。一是维护…"
