    "description": "2026年09月28日 80.1% 1—8月，全国水利建设落实地方政府专项债券、银行贷款、社会资本共3128.1亿元，其中，引入民间资本134.3亿元，同比增长80.1%。 广东省湛江市麻章区，双向四车道的雷湖快线车来车往。路面下7米多深处，一条管线横穿而过，不声不响、悄然贯通。 沿道路一侧“环北部湾广东水资源配置工程（施工D2标）”牌子所指方向，可见一口巨大的工作井。爬上一人高的井沿，再顺着窄窄的铁架子下到井底，便置身一个宽大的圆形“…",
    "content": "2026年09月28日 80.1% 1—8月，全国水利建设落实地方政府专项债券、银行贷款、社会资本共3128.1亿元，其中，引入民间资本134.3亿元，同比增长80.1%。 广东省湛江市麻章区，双向四车道的雷湖快线车来车往。路面下7米多深处，一条管线横穿而过，不声不响、悄然贯通。 沿道路一侧“环北部湾广东水资源配置工程（施工D2标）”牌子所指方向，可见一口巨大的工作井。爬上一人高的井沿，再顺着窄窄的铁架子下到井底，便置身一个宽大的圆形“洞口”——并排走三四个人绰绰有余。望向“洞内”，一片漆黑，不时有对面工作井里施工…"
