    "description": "2026年09月28日 人口流动、社保参保、出租屋登记……一个季度，几个系统，十几张表格。“很多数据上个月刚填过，换个部门又来催一遍”，一次采访中，海南海口市琼山区一名网格员坦言，“有时几乎是‘专职’填表，抽空办事”。 这句话之所以扎心，在于它精准刺中了一个基层痼疾：本该在街头巷尾、田间地头奔走的基层干部，硬生生被报表堆成了“案头秀才”。重复填、多头报、限时交，消耗了他们大量的时间和精力。 问题在哪里，改革就要推进到哪里。2024年12…",
    "content": "2026年09月28日 人口流动、社保参保、出租屋登记……一个季度，几个系统，十几张表格。“很多数据上个月刚填过，换个部门又来催一遍”，一次采访中，海南海口市琼山区一名网格员坦言，“有时几乎是‘专职’填表，抽空办事”。 这句话之所以扎心，在于它精准刺中了一个基层痼疾：本该在街头巷尾、田间地头奔走的基层干部，硬生生被报表堆成了“案头秀才”。重复填、多头报、限时交，消耗了他们大量的时间和精力。 问题在哪里，改革就要推进到哪里。2024年12月，国务院办公厅印发《基层报表数据“只报一次”工作指引》。海南在海口市琼山区启动…"
