    "description": "2026年09月28日 行走在内蒙古鄂尔多斯，微风夹杂着草木的清香。在库布其沙漠腹地，穿沙公路像一条黑色绸带，笔直切开浩瀚黄沙；公路两侧，沙柳编织的网格沙障牢牢锁住流沙，柠条、羊柴等灌木在风里蓄势生长；再往远处看，成片光伏板铺展开来，在阳光下熠熠生辉…… 鄂尔多斯是我国荒漠化防治和“三北”等重点生态工程建设的重要区域之一。如何把生态保护、产业转型和群众增收统筹起来？答案，写在一望无垠的沙海里，也写在一座座矿山、一片片园区和一个个平常的日…",
    "content": "2026年09月28日 行走在内蒙古鄂尔多斯，微风夹杂着草木的清香。在库布其沙漠腹地，穿沙公路像一条黑色绸带，笔直切开浩瀚黄沙；公路两侧，沙柳编织的网格沙障牢牢锁住流沙，柠条、羊柴等灌木在风里蓄势生长；再往远处看，成片光伏板铺展开来，在阳光下熠熠生辉…… 鄂尔多斯是我国荒漠化防治和“三北”等重点生态工程建设的重要区域之一。如何把生态保护、产业转型和群众增收统筹起来？答案，写在一望无垠的沙海里，也写在一座座矿山、一片片园区和一个个平常的日子里。 生态绿：从“沙进人退”到“绿进沙退” 在鄂尔多斯达拉特旗昭君镇和恩格贝镇…"
