    "description": "2026年09月28日 山间茶园叠翠，制瓷水碓声声。瑶河潺潺，绕过南宋的窑火，经过明清的商幡，流淌至江西景德镇市浮梁县瑶里古镇。 瑶里，古称“窑里”，因唐宋时期瓷业窑厂遍布而得名。后又因青山绿水，如同天上瑶池，故雅化为“瑶里”，是景德镇瓷茶文化发源地之一。 习近平总书记指出，中华优秀传统文化自古至今从未断流，陶瓷是中华瑰宝，是中华文明的重要名片。 守护瓷茶文脉，活化非遗技艺。今日瑶里，正通过创造性转化、创新性发展，在山水间唱响瓷源茶乡的…",
    "content": "2026年09月28日 山间茶园叠翠，制瓷水碓声声。瑶河潺潺，绕过南宋的窑火，经过明清的商幡，流淌至江西景德镇市浮梁县瑶里古镇。 瑶里，古称“窑里”，因唐宋时期瓷业窑厂遍布而得名。后又因青山绿水，如同天上瑶池，故雅化为“瑶里”，是景德镇瓷茶文化发源地之一。 习近平总书记指出，中华优秀传统文化自古至今从未断流，陶瓷是中华瑰宝，是中华文明的重要名片。 守护瓷茶文脉，活化非遗技艺。今日瑶里，正通过创造性转化、创新性发展，在山水间唱响瓷源茶乡的新声。 守&nbsp;&nbsp;护 早在17世纪，瑶里古镇东埠古码头就成为景德…"
