    "title": "07版 - 排水沟盖板断裂 影响环境卫生和安全（身边事）",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202609/28/content_30183378.html",
    "pub_date": "2026-09-28 08:26:03",
    "author": "",
    "description": "2026年09月28日 我们是辽宁大连市金州区解放路花园小区居民。小区20号楼西侧，此前是一片旧房和市场，后来进行了拆除。但拆除后，地下污水排水沟的水泥盖板被压塌了，导致污水沟裸露在外（见图）。现场臭气弥漫，蚊虫滋生，导致周边居民无法正常开窗通风，严重干扰日常生活。同时沟体无遮盖、无防护，存在较大安全隐患。还有一些建筑垃圾堆积在此处，无人清理。请有关部门关注该问题，尽快对排水沟盖板进行封闭，并清运建筑垃圾。 人民网“领导留言板”网友 2…",
