    "content": "2026年09月28日 9月12日，习近平主席在印度新德里出席金砖国家领导人第十八次会晤第一阶段会议，发表题为《共担时代责任&nbsp;&nbsp;勇做先锋力量》的重要讲话，强调：“金砖国家要坚定站在历史正确一边，勇做时代先锋，引领国际秩序朝着更加公正合理的方向发展，携手推动构建人类命运共同体。”习近平主席提出对金砖国家勇做时代先锋的深切期许：“做促进创新发展的先锋”“做维护和平稳定的先锋”“做推动文明互鉴的先锋”“做改革完善全球治理的先锋”。这些重要论述，立足于金砖合作机制创立20周年、迈入“大金砖合作”高质量发…"
