    "description": "2026年09月28日 在辽宁省博物馆“古代辽宁”1号展厅，一件距今5000余年的玉猪龙（见图，辽宁省博物馆供图）陈列于独立展柜。猪首龙身的形制，使它成为中华龙图腾最早的实物原型之一，也是辽宁省博物馆的馆标形象，彰显出辽博“溯源辽河、贯通古今”的办馆内涵。 记者：玉猪龙是如何成为辽宁省博物馆馆标形象的？ 王筱雯：这是历史价值、地域文化、公众与专家共识共同选择的结果。2006年12月，馆方开展“辽博十大镇馆之宝”全民评选，候选文物涵盖书画…",
