    "content": "2026年09月28日 吕怀兴近照，AI修饰生成素描画 \"> 在外界看来，再生塑料是门低成本、高回报“变废为宝”的生意，可在我眼里，这是一场和杂质反复较劲的技术攻坚。 长期以来，废塑料成分杂、污染重，回收后大多只能降级加工成花盆、衣架这类日用品，“低质低值”几乎成了行业默认的共识。但我始终认为：卡住再生塑料价值上限的，不是塑料本身，而是那些最容易被忽略的细小杂质。抱着这种念头，我们团队一头扎进杂质管控的全流程工艺研发。 要破解杂质难题，得先从源头换思路。过去收废塑料像“拆盲盒”，来什么处理什么，不同材质、不同脏污程…"
