    "description": "2026年09月28日 父亲写得一手好毛笔字。 他是有童子功的。幼时在村里私塾读书，日日描红练字，不知描了多少本，手掌心也不知挨了多少回戒尺责打。先生那句教诲，他记了一辈子：毛笔字，是一个人的脸面。 古徽州，“十户之村，不废诵读”，文风蔚然。倘若字迹潦草杂乱，会被笑作“鸡爪爬”，那是要“跌大股”（方言，很丢人）的。 少年时，父亲去一位徽州名中医家当学生。每天除了随老师“望闻问切”外，就是抄药方。18岁，自己悬壶开业。我见过他几张当年开的…",
