    "description": "2026年09月28日 登泰山，有若干路径，我们是乘坐缆车直抵山顶。没有沿着山道观摩石刻和碑碣，却在空中看着漫山的绿树，听同行者讲述张耀南植树造林的历史。 在上世纪50年代，泰山的林木遭遇砍伐，水土流失严重。担任泰山林场场长那年，张耀南已经58岁了。他拄着拐杖，背着水壶，走遍泰山所有的沟壑。他带领群众在山上挖坑植树，在陡峭崖壁上用绳索束腰，悬在半空把混着泥土的树种抛入岩隙。从1959年开始扎根泰山，到1974年病逝，10多年间，张耀南带…",
    "content": "2026年09月28日 登泰山，有若干路径，我们是乘坐缆车直抵山顶。没有沿着山道观摩石刻和碑碣，却在空中看着漫山的绿树，听同行者讲述张耀南植树造林的历史。 在上世纪50年代，泰山的林木遭遇砍伐，水土流失严重。担任泰山林场场长那年，张耀南已经58岁了。他拄着拐杖，背着水壶，走遍泰山所有的沟壑。他带领群众在山上挖坑植树，在陡峭崖壁上用绳索束腰，悬在半空把混着泥土的树种抛入岩隙。从1959年开始扎根泰山，到1974年病逝，10多年间，张耀南带领群众种下的树，如今都已郁郁葱葱。 面对泰山，张耀南以勤苦的劳动，埋头做了一件具…"
