    "content": "记者9月28日从中国科学院获悉，《中国科学院“十五五”发展规划》近日正式发布。规划聚焦抢占科技制高点核心任务，明确了“十五五”时期中国科学院科技事业发展的战略重点，围绕基础研究、战略高技术和可持续发展三大领域体系化部署科技攻关重点方向，着力加强人工智能赋能科学研究，持续强化科技基础能力建设，统筹优化区域科技布局，并围绕国际一流科研机构建设目标，从教育科技人才一体发展、国家科学技术思想库建设、科研组织变革和管理创新、科技成果转移转化、国际科技交流合作等方面，提出一系列改革发展任务。（记者 胡喆）"
