    "description": "由诗人王寅主持策划的“诗歌来到美术馆”是上海民生美术馆一项持续十多年的“诗歌+艺术”美术馆公众项目，欧阳江河、翟永明、西川、阿多尼斯、谷川俊太郎等多位海内外著名诗人都曾参与过该项目。9月27日是该活动的第100期：智利诗人马里奥·梅伦德斯向走进民生美术馆的上海读者朗读了四首诗，本期活动由英美文学学者、华东师大国际汉语文化学院比较文学系主任金雯主持。 梅伦德斯作为第一百期嘉宾，现场朗朗了向秘鲁诗人巴列霍致意的《忏悔录》、献给智利左翼诗人洛…",
    "content": "由诗人王寅主持策划的“诗歌来到美术馆”是上海民生美术馆一项持续十多年的“诗歌+艺术”美术馆公众项目，欧阳江河、翟永明、西川、阿多尼斯、谷川俊太郎等多位海内外著名诗人都曾参与过该项目。9月27日是该活动的第100期：智利诗人马里奥·梅伦德斯向走进民生美术馆的上海读者朗读了四首诗，本期活动由英美文学学者、华东师大国际汉语文化学院比较文学系主任金雯主持。 梅伦德斯作为第一百期嘉宾，现场朗朗了向秘鲁诗人巴列霍致意的《忏悔录》、献给智利左翼诗人洛约拉的《公牛舞》、取材墨西哥丧葬传统的《丧事邀请函》，最后是首轻快的短诗《彼此彼…"
