    "description": "澎湃新闻·文学花边推出栏目“文学双周记”，以半月为期，为读者带来国内外文学资讯。本期为9月14日至27日的资讯汇总。 诺贝尔文学奖将于10月8日揭晓 2026年诺贝尔文学奖公布时间 图源：诺贝尔奖基金会 2026年诺贝尔文学奖将于北京时间10月8日晚揭晓。临近开奖，瑞典学院院士艾伦·马特松在诺贝尔奖基金会的视频中谈起评选工作：面对一位候选作家，即使起初读不懂，或并不喜欢其作品，评委仍需继续读下去。评奖需要评委暂时放下个人阅读趣味，认真进…",
