    "content": "新华社伦敦9月27日电（记者张枫）美国在线影视平台奈飞公司近期推出基于英国经典小说《傲慢与偏见》的改编新剧，激发年轻观众对小说作者简·奥斯汀的新一轮“考古热”。在那个婚恋关乎女性生存与命运的时代，简·奥斯汀用轻盈幽默的笔触映照社会现实，以看似平淡的故事揭示复杂人性，留下了为数不多却部部深入人心的作品。 当下流通的英国纸币中，简·奥斯汀的肖像印在10英镑纸币背面。曾频繁出现在她小说中的英国西南部古城巴斯，每年仍会以一场盛装游行纪念她：人们穿上摄政时代的服饰，穿行于古城街巷，重现两百年前的风雅与浪漫，体验简·奥斯汀所属…"
