    "content": "新华社贝鲁特9月27日电（记者申峰）黎巴嫩真主党27日在首都贝鲁特南郊举行纪念其前领导人哈桑·纳斯鲁拉去世两周年活动。真主党现任领导人纳伊姆·卡西姆重申将坚持“抵抗”，不会向以色列“投降”。 据真主党旗下灯塔电视台报道，数千人参加纪念活动。卡西姆在活动上发表电视讲话说，真主党“只会继续前进，不会被击败”。他重申拒绝解除武装，称没有“抵抗”就无法生存，并呼吁黎巴嫩各社会群体保持团结。 黎巴嫩、以色列和美国6月26日在美国华盛顿完成谈判后，宣布达成框架协议。根据协议设想，以军将从黎南部部分地区撤出，由黎军队接管当地安全…"
