    "description": "9月28日，一批重点高铁线路开通运营，京港高铁雄安至商丘段、西渝高铁西安至安康段、宜昌至兴山高铁、哈尔滨至伊春高铁集中亮相。 四条新线穿越华北、西北、华中、东北，进一步织密“八纵八横”高速铁路网，压缩区域时空距离，便利沿线群众出行，为区域高质量发展注入交通新动能。 记者：樊曦、苏凯洋 海报制作：胡戈 新华社国内部出品",
    "content": "9月28日，一批重点高铁线路开通运营，京港高铁雄安至商丘段、西渝高铁西安至安康段、宜昌至兴山高铁、哈尔滨至伊春高铁集中亮相。 四条新线穿越华北、西北、华中、东北，进一步织密“八纵八横”高速铁路网，压缩区域时空距离，便利沿线群众出行，为区域高质量发展注入交通新动能。 记者：樊曦、苏凯洋 海报制作：胡戈 新华社国内部出品"
