    "description": "新华社耶路撒冷9月27日电（记者庞昕熠 王卓伦）以色列外交部长萨尔27日说，以方决定不再承认荷兰驻拉姆安拉代表处外交人员的外交身份，相关人员享有的外交特权与豁免权将在7天后到期。 萨尔当天在社交媒体上称，他已通知荷兰驻以色列大使馆，在约旦河西岸城市拉姆安拉工作的荷兰外交人员必须在7天内交还由以色列签发的外交文件，此后他们的外交特权和豁免权将失效。 以方称，此举是为回应荷兰近期生效的一项进口禁令，该禁令禁止进口和销售来自约旦河西岸和戈兰高…",
    "content": "新华社耶路撒冷9月27日电（记者庞昕熠 王卓伦）以色列外交部长萨尔27日说，以方决定不再承认荷兰驻拉姆安拉代表处外交人员的外交身份，相关人员享有的外交特权与豁免权将在7天后到期。 萨尔当天在社交媒体上称，他已通知荷兰驻以色列大使馆，在约旦河西岸城市拉姆安拉工作的荷兰外交人员必须在7天内交还由以色列签发的外交文件，此后他们的外交特权和豁免权将失效。 以方称，此举是为回应荷兰近期生效的一项进口禁令，该禁令禁止进口和销售来自约旦河西岸和戈兰高地的以色列非法定居点的产品。 荷兰政府7月宣布，从9月22日起对以色列非法定居点…"
