    "content": "新华社华盛顿9月27日电（记者徐剑梅 黄强）美国总统特朗普27日表示，他预计美国和伊朗将在接下来一周内重启谈判。 据美国阿克西奥斯新闻网站报道，特朗普当天在接受该媒体电话采访时作出上述表态。 特朗普还说，他“一直在考虑”是否恢复对伊朗的军事打击，同时美军正在协助从霍尔木兹海峡运出“大量石油”。 这家媒体援引地区消息人士的话称，预计美伊最早将于28日举行新一轮间接对话，卡塔尔等调解方正在斡旋，但美伊在关键问题上存在巨大分歧。伊朗希望将谈判重点放在霍尔木兹海峡通航和解除美对伊海上封锁上，特朗普政府则要求伊朗同意在核问题…"
