    "content": "新华社科威特城9月27日电（记者尹炣）萨那消息：也门胡塞武装27日称，过去24小时内，沙特阿拉伯战机对也门5个省发动26次空袭。也门政府军方面则表示，过去3天对胡塞武装军事目标实施了数百次打击。 胡塞武装军事发言人叶海亚·萨雷亚当日在社交媒体发表声明称，数架F-15战斗机从沙特的海米斯穆谢特空军基地起飞，对也门塔伊兹、焦夫、马里卜、扎马尔和萨达5省发动26次空袭，造成人员伤亡。但声明未提及具体伤亡数字。 声明称，自本轮冲突升级以来，沙特发动的空袭和导弹袭击已达1085次。 另据也门政府军27日称，过去72小时内，政…"
